function parseQuery(qs) {
  if (typeof qs !== 'string') {
    throw new TypeError('qs must be a string');
  }

  qs = qs.replace(/^\?/, ''); // Remove optional leading '?'
  if (qs === '') return {};

  const result = Object.create(null);
  const pairs = qs.split('&');

  for (const pair of pairs) {
    if (pair.trim() === '') continue; // Skip empty pairs

    const [key, value] = pair.split('=', 2);
    const decodedKey = decodeURIComponent(key.replace(/\+/g, ' '));
    if (decodedKey === '') continue; // Skip pairs with empty decoded keys

    if (decodedKey in result) {
      if (!Array.isArray(result[decodedKey])) {
        result[decodedKey] = [result[decodedKey]];
      }
      result[decodedKey].push(decodeURIComponent(value ? value.replace(/\+/g, ' ') : ''));
    } else {
      result[decodedKey] = decodeURIComponent(value ? value.replace(/\+/g, ' ') : '');
    }
  }

  return result;
}

module.exports = { parseQuery };
