function topoSort(graph) {
  const inDegree = {};
  const result = [];
  const tasks = Object.keys(graph);

  // Initialize in-degree for all tasks
  tasks.forEach(task => {
    inDegree[task] = 0;
  });

  // Calculate in-degree for each task
  tasks.forEach(task => {
    graph[task].forEach(dep => {
      inDegree[dep]++;
    });
  });

  // Queue for tasks with zero in-degree
  const queue = tasks.filter(task => inDegree[task] === 0);

  while (queue.length > 0) {
    const task = queue.shift();
    result.push(task);

    graph[task].forEach(dep => {
      inDegree[dep]--;
      if (inDegree[dep] === 0) {
        queue.push(dep);
      }
    });
  }

  // Check for cycles
  if (result.length !== tasks.length) {
    throw new Error('cycle');
  }

  return result;
}

module.exports = { topoSort };
