def allocate(total, weights):
    if total < 0:
        raise ValueError("total must be non-negative")
    if not weights:
        raise ValueError("weights must not be empty")
    if any(w < 0 for w in weights):
        raise ValueError("all weights must be non-negative")
    if all(w == 0 for w in weights):
        raise ValueError("all weights must be non-zero")

    total_weight = sum(weights)
    if total_weight == 0:
        raise ValueError("sum of weights must be non-zero")

    shares = [total * w // total_weight for w in weights]
    remainder = total - sum(shares)
    remainder_indices = sorted(range(len(weights)), key=lambda i: (weights[i] / total_weight - shares[i] / total_weight, i))

    for i in remainder_indices:
        if remainder == 0:
            break
        shares[i] += 1
        remainder -= 1

    return shares
