function topoSort(graph) {
  const inDegree = {};
  const adjList = {};
  const result = [];

  // Initialize in-degree and adjacency list
  for (const task in graph) {
    inDegree[task] = 0;
    adjList[task] = [];
  }

  // Populate in-degree and adjacency list
  for (const task in graph) {
    graph[task].forEach(dependency => {
      if (!inDegree[dependency]) inDegree[dependency] = 0;
      if (!adjList[dependency]) adjList[dependency] = [];
      adjList[dependency].push(task);
      inDegree[task]++;
    });
  }

  // Find nodes with zero in-degree
  const queue = [];
  for (const task in inDegree) {
    if (inDegree[task] === 0) {
      queue.push(task);
    }
  }

  // Process the queue
  while (queue.length > 0) {
    if (queue.length > 1) {
      // Sort tasks lexicographically
      queue.sort();
    }
    const task = queue.shift();
    result.push(task);

    // Decrease the in-degree of adjacent nodes
    adjList[task].forEach(neighbor => {
      inDegree[neighbor]--;
      if (inDegree[neighbor] === 0) {
        queue.push(neighbor);
      }
    });
  }

  // Check for cycles
  if (result.length !== Object.keys(graph).length) {
    throw new Error('cycle');
  }

  return result;
}

module.exports = { topoSort };
