def allocate(total, weights):
    if total < 0:
        raise ValueError("total must be non-negative")
    if not weights:
        raise ValueError("weights list must not be empty")
    if any(weight < 0 for weight in weights):
        raise ValueError("all weights must be non-negative")
    if all(weight == 0 for weight in weights):
        raise ValueError("at least one weight must be non-zero")

    sum_weights = sum(weights)
    share = total * sum(weights) // (sum_weights ** 2)
    remainder = total - share * sum_weights
    result = [share * weight for weight in weights]

    for i in range(remainder):
        max_remainder = max((result[j] - share * weights[j], j) for j in range(len(weights)))[1]
        result[max_remainder] += 1

    return result
