function topoSort(graph) {
  const inDegree = {};
  const result = [];
  const zeroInDegree = [];

  // Initialize in-degree for each task
  for (const task in graph) {
    inDegree[task] = 0;
    graph[task].forEach(dependency => {
      if (inDegree[dependency] === undefined) {
        inDegree[dependency] = 0;
      }
      inDegree[dependency]++;
    });
  }

  // Find tasks with zero in-degree
  for (const task in inDegree) {
    if (inDegree[task] === 0) {
      zeroInDegree.push(task);
    }
  }

  // Process tasks with zero in-degree
  while (zeroInDegree.length > 0) {
    const task = zeroInDegree.sort()[0];
    zeroInDegree.shift();
    result.push(task);

    graph[task].forEach(dependency => {
      inDegree[dependency]--;
      if (inDegree[dependency] === 0) {
        zeroInDegree.push(dependency);
      }
    });

    delete graph[task];
  }

  // Check for cycles
  if (Object.keys(graph).length > 0) {
    throw new Error('cycle detected');
  }

  return result;
}

