function topoSort(graph) {
  const inDegree = {};
  const result = [];
  const queue = [];

  // Initialize in-degree and queue
  for (const task in graph) {
    inDegree[task] = 0;
  }
  for (const task in graph) {
    for (const dependency of graph[task]) {
      inDegree[dependency]++;
    }
  }
  for (const task in inDegree) {
    if (inDegree[task] === 0) {
      queue.push(task);
    }
  }

  // Topological sort
  while (queue.length > 0) {
    const current = queue.shift();
    result.push(current);

    for (const neighbor of graph[current]) {
      inDegree[neighbor]--;
      if (inDegree[neighbor] === 0) {
        queue.push(neighbor);
      }
    }
  }

  // Check for cycle
  if (result.length !== Object.keys(graph).length) {
    throw new Error('cycle');
  }

  return result;
}

module.exports = { topoSort };
