function topoSort(graph) {
  const inDegree = {};
  const adjacencyList = {};
  const result = [];
  const zeroInDegree = [];

  // Initialize in-degree and adjacency list
  for (const task in graph) {
    inDegree[task] = 0;
    adjacencyList[task] = [];
  }

  // Populate in-degree and adjacency list
  for (const task in graph) {
    for (const dependency of graph[task]) {
      inDegree[dependency]++;
      adjacencyList[task].push(dependency);
    }
  }

  // Find tasks with zero in-degree
  for (const task in inDegree) {
    if (inDegree[task] === 0) {
      zeroInDegree.push(task);
    }
  }

  // Perform topological sort
  while (zeroInDegree.length > 0) {
    const task = zeroInDegree.sort()[0];
    zeroInDegree.shift();
    result.push(task);

    for (const neighbor of adjacencyList[task]) {
      inDegree[neighbor]--;
      if (inDegree[neighbor] === 0) {
        zeroInDegree.push(neighbor);
      }
    }
  }

  // Check for cycles
  if (result.length !== Object.keys(graph).length) {
    throw new Error('cycle');
  }

  return result;
}

module.exports = { topoSort };
