        raise ValueError("all weights must be non-negative")
    if sum(weights) == 0:
        raise ValueError("sum of weights must be non-zero")

    total_weights = sum(weights)
    base_share = total // total_weights
    remainder = total % total_weights
    shares = [base_share] * len(weights)

    for i in range(remainder):
        max_remainder = float('-inf')
        max_index = -1
        for j, weight in enumerate(weights):
            if weight > 0:
                fractional_part = (base_share + 1) * weight / total_weights - shares[j]
                if fractional_part > max_remainder:
                    max_remainder = fractional_part
                    max_index = j
        shares[max_index] += 1

