def parse_duration(text):
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if not text:
        raise ValueError("text cannot be empty")

    units = {
        'd': 86400,
        'h': 3600,
        'm': 60,
        's': 1
    }

    seconds = 0
    i = 0
    while i < len(text):
        if not text[i].isdigit():
            raise ValueError("number must precede unit")
        j = i
        while j < len(text) and text[j].isdigit():
            j += 1
        number = int(text[i:j])

        if j == len(text) or text[j] not in units:
            raise ValueError("unknown or misplaced unit")
        unit = text[j]
        if j > i + 1 and text[i+1] == unit:
            raise ValueError("repeated unit")

        seconds += number * units[unit]

        i = j + 1

    return seconds
