      if (!adjacencyList[dependency]) adjacencyList[dependency] = [];
      adjacencyList[dependency].push(task);
      inDegree[task]++;
    });
  }

  // Find nodes with zero in-degree
  const queue = Object.keys(inDegree).filter(task => inDegree[task] === 0);

  while (queue.length > 0) {
    // Sort nodes with zero in-degree lexicographically
    queue.sort();

    const task = queue.shift();
    result.push(task);

    // Reduce in-degree of adjacent nodes
    adjacencyList[task].forEach(neighbor => {
      inDegree[neighbor]--;
      if (inDegree[neighbor] === 0) {
        queue.push(neighbor);
      }
    });
  }

  // Check for cycles
  if (result.length !== Object.keys(graph).length) {
    throw new Error('Cycle detected in dependencies');
  }

