    if total < 0:
        raise ValueError("total must not be negative")
    if not weights:
        raise ValueError("weights must not be empty")
    if any(weight < 0 for weight in weights):
        raise ValueError("weights must not contain negative values")
    if all(weight == 0 for weight in weights):
        raise ValueError("weights must not be all zero")

    total_weight = sum(weights)
    shares = [total * weight // total_weight for weight in weights]
    remainder = total - sum(shares)
    remainders = [(total * weight % total_weight, i) for i, weight in enumerate(weights)]
    remainders.sort(reverse=True)

    for r, i in remainders:
        if remainder <= 0:
            break
        shares[i] += 1
        remainder -= 1

    return shares
