def allocate(total, weights):
    if total < 0:
        raise ValueError("total must not be negative")
    if not weights:
        raise ValueError("weights must not be empty")
    if any(weight < 0 for weight in weights):
        raise ValueError("all weights must be non-negative")
    if all(weight == 0 for weight in weights):
        raise ValueError("all weights must not be zero")

    total_weight = sum(weights)
    base_share = total // total_weight
    remainders = [total % total_weight] + sorted([(total * weight // total_weight - base_share, i) for i, weight in enumerate(weights)], reverse=True)

    result = [base_share] * len(weights)
    for i in range(remainders[0][1], len(weights)):
        if remainders[i][0] > 0:
            result[i] += 1
            remainders[0][0] -= 1

    return result
