    for (const dependency of graph[task]) {
      if (!graph.hasOwnProperty(dependency)) continue;
      nodes.add(dependency);
      if (!inDegree.hasOwnProperty(dependency)) {
        inDegree[dependency] = 0;
      }
      inDegree[dependency]++;
    }
  }

  // Enqueue all nodes with zero in-degree
  const queue = [];
  for (const task of nodes) {
    if (inDegree[task] === 0) {
      queue.push(task);
