    result.push(task);

    for (const dependency of graph[task] || []) {
      if (inDegree[dependency] > 0) {
        inDegree[dependency]--;
        if (inDegree[dependency] === 0) {
          queue.push(dependency);
        }
      }
    }
  }

  // Check for cycles
  if (result.length !== nodes.size) {
    throw new Error('cycle');
  }

  return result;
}

