  emit(event, ...args) {
    if (!this.events[event]) {
      return false;
    }
    const listeners = this.events[event].slice();
    listeners.forEach(listener => listener.apply(this, args));
    return listeners.length > 0;
  }

  listenerCount(event) {
    return this.events[event] ? this.events[event].length : 0;
  }
}

