function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const parts = spec.trim().split(',').map(part => part.trim());
  const result = new Set();

  for (const part of parts) {
    if (part === '') {
      throw new SyntaxError('empty part');
    }

    if (part.includes('+')) {
      throw new SyntaxError('plus sign not allowed');
    }

    if (part.includes('.')) {
      throw new SyntaxError('decimals not allowed');
    }

    if (part.includes(' ')) {
      throw new SyntaxError('whitespace not allowed inside part');
    }

    if (part.includes('--')) {
      throw new SyntaxError('more than one dash not allowed');
    }

    if (part.includes('-')) {
      const [lo, hi] = part.split('-').map(Number);
      if (lo > hi) {
        throw new RangeError('range start must not exceed range end');
      }
      for (let i = lo; i <= hi; i++) {
        result.add(i);
      }
    } else {
      result.add(Number(part));
    }
  }

  return Array.from(result).sort((a, b) => a - b);
}

module.exports = { expandRanges };
