      if (lo > hi) {
        throw new RangeError('start of range must not exceed end');
      }
      for (let i = lo; i <= hi; i++) {
        result.add(i);
      }
    } else {
      const num = Number(part);
      if (isNaN(num) || num < 0) {
        throw new SyntaxError('invalid number in part');
      }
      result.add(num);
    }
  }

  return Array.from(result).sort((a, b) => a - b);
}

