function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const parts = spec.split(',').map(part => part.trim());
  const result = new Set();

  for (const part of parts) {
    if (part === '') {
      throw new SyntaxError('empty part');
    }

    const dashIndex = part.indexOf('-');
    if (dashIndex === -1) {
      const num = parseInt(part, 10);
      if (isNaN(num)) {
        throw new SyntaxError('non-numeric part');
      }
      result.add(num);
    } else {
      const lo = parseInt(part.substring(0, dashIndex), 10);
      const hi = parseInt(part.substring(dashIndex + 1), 10);
      if (isNaN(lo) || isNaN(hi)) {
        throw new SyntaxError('non-numeric range part');
      }
      if (lo > hi) {
        throw new RangeError('lo must not exceed hi in range');
      }
      for (let i = lo; i <= hi; i++) {
        result.add(i);
      }
    }
  }

  return Array.from(result).sort((a, b) => a - b);
}

module.exports = { expandRanges };
