      const end = parseInt(hi, 10);
      if (start > end) {
        throw new RangeError('start must not exceed end');
      }
      for (let i = start; i <= end; i++) {
        numbers.add(i);
      }
    } else {
      numbers.add(parseInt(part, 10));
    }
  }

  return Array.from(numbers).sort((a, b) => a - b);
}

