    if not isinstance(text, str):
        raise TypeError("text must be a string")

    text = text.strip()
    if not text:
        raise ValueError("text cannot be empty")

    parts = text.split()
    if len(parts) > 2:
        raise ValueError("text must have at most one space")

    time_part = parts[0]
    if ':' not in time_part:
        raise ValueError("time part must contain a colon")

    time, am_pm = time_part.rsplit(' ', 1) if len(parts) == 2 else (time_part, None)
    if am_pm and am_pm.lower() not in ('am', 'pm'):
        raise ValueError("suffix must be 'AM' or 'PM'")

    hour, minute = map(str.strip, time.split(':'))
    if not hour.isdigit() or not minute.isdigit():
        raise ValueError("hour and minute must be digits")

    hour = int(hour)
    minute = int(minute)

    if hour < 1 or hour > 12:
        raise ValueError("hour must be between 1 and 12")
    if minute < 0 or minute > 59:
        raise ValueError("minute must be between 0 and 59")

    if hour == 12:
        hour = 0 if am_pm and am_pm.lower() == 'am' else 12

    return f"{hour:02}:{minute:02}"

