function addDays(dateStr, days) {
  if (typeof dateStr !== 'string') {
    throw new TypeError('dateStr must be a string');
  }
  if (typeof days !== 'number' || !Number.isInteger(days)) {
    throw new TypeError('days must be an integer');
  }

  const dateParts = dateStr.split('-');
  if (dateParts.length !== 3) {
    throw new RangeError('dateStr must be in the format YYYY-MM-DD');
  }
  const year = parseInt(dateParts[0], 10);
  const month = parseInt(dateParts[1], 10) - 1;
  const day = parseInt(dateParts[2], 10);

  if (isNaN(year) || isNaN(month) || isNaN(day)) {
    throw new RangeError('dateStr must be a valid calendar date');
  }
  if (year < 1 || year > 9999) {
    throw new RangeError('year must be between 0001 and 9999');
  }
  if (month < 0 || month > 11) {
    throw new RangeError('month must be between 01 and 12');
  }
  if (day < 1) {
    throw new RangeError('day must be at least 01');
  }

  const date = new Date(Date.UTC(year, month, day));
  const newDate = new Date(date.getTime() + days * 24 * 60 * 60 * 1000);
  const newYear = newDate.getUTCFullYear();
  const newMonth = newDate.getUTCMonth() + 1;
  const newDay = newDate.getUTCDate();

  return `${newYear.toString().padStart(4, '0')}-${newMonth.toString().padStart(2, '0')}-${newDay.toString().padStart(2, '0')}`;
}

module.exports = { addDays };
