def is_balanced(code):
    stack = []
    i = 0
    while i < len(code):
        if code[i] == '"':
            j = i + 1
            while j < len(code) and (code[j] != '"' or (j > 1 and code[j-1] == '\\')):
                j += 1
            if j == len(code):
                return False
            i = j + 1
        elif code[i] in '([{':
            stack.append(code[i])
        elif code[i] in ')]}':
            if not stack or (code[i] == ')' and stack[-1] != '(') or (code[i] == ']' and stack[-1] != '[') or (code[i] == '}' and stack[-1] != '{'):
                return False
            stack.pop()
        i += 1
    return not stack
