def add_months(date_str, n):
    if not isinstance(n, int):
        raise TypeError("n must be an integer")

    try:
        date_parts = map(int, date_str.split('-'))
        year, month, day = date_parts
    except (ValueError, TypeError):
        raise ValueError("date_str must be in YYYY-MM-DD format")

    if not (1 <= year <= 9999) or month < 1 or month > 12 or day < 1:
        raise ValueError("date_str must be in YYYY-MM-DD format")

    try:
        target_date = datetime(year, month, day)
    except ValueError:
        raise ValueError("date_str must be in YYYY-MM-DD format")

    if n > 0:
        for _ in range(n):
            month += 1
            if month > 12:
                year += 1
                month = 1
            try:
                target_date = datetime(year, month, day)
            except ValueError:
                day = (datetime(year, month, 1) - timedelta(days=1)).day
                target_date = datetime(year, month, day)
    elif n < 0:
        for _ in range(-n):
            if month == 1:
                year -= 1
                month = 12
            else:
                month -= 1
            try:
                target_date = datetime(year, month, day)
            except ValueError:
                day = (datetime(year, month, 1) - timedelta(days=1)).day
                target_date = datetime(year, month, day)

    return target_date.strftime("%Y-%m-%d")

