def maze_steps(grid):
    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    start = None
    end = None

    for r in range(rows):
        if len(grid[r]) != cols:
            raise ValueError("rows must all be the same length")
        for c in range(cols):
            if grid[r][c] == 'S':
                if start is not None:
                    raise ValueError("there must be exactly one 'S'")
                start = (r, c)
            elif grid[r][c] == 'E':
                if end is not None:
                    raise ValueError("there must be exactly one 'E'")
                end = (r, c)
            elif grid[r][c] not in 'SE.#':
                raise ValueError("grid must only contain 'S', 'E', '#', and '.'")

    if start is None or end is None:
        raise ValueError("there must be exactly one 'S' and one 'E'")

    queue = deque([start])
    visited = set([start])
    steps = 0

    while queue:
        for _ in range(len(queue)):
            x, y = queue.popleft()
            if (x, y) == end:
                return steps
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] != '#' and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append((nx, ny))
        steps += 1

    return -1
