    throw new RangeError('Invalid date format');
  }
  if (birth > on) {
    throw new RangeError('on must not be earlier than birth');
  }
  const birthDate = new Date(birth);
  const onDate = new Date(on);
  const days = daysBetweenDates(birthDate, onDate);
  const years = Math.floor(days / 365.25);
  const hasBirthday = days - years * 365.25 >= 365;
  return years + (hasBirthday ? 1 : 0);
}

