        for j in range(cols):
            if grid[i][j] not in "SE.#":
                raise ValueError("Invalid character in the grid")
            if grid[i][j] == "S":
                start = (i, j)
            elif grid[i][j] == "E":
                end = (i, j)

    if start is None or end is None or grid.count("S") != 1 or grid.count("E") != 1:
        raise ValueError("There must be exactly one start and one end in the grid")

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    queue = deque([start])
    visited = set([start])

    steps = 0

    while queue:
        for _ in range(len(queue)):
            x, y = queue.popleft()
            if (x, y) == end:
