from collections import deque

def maze_steps(grid):
    if not grid or not grid[0]:
        raise ValueError("Grid is empty")

    rows, cols = len(grid), len(grid[0])
    if not all(len(row) == cols for row in grid):
        raise ValueError("Rows are not all the same length")

    start, end = None, None
    for i, row in enumerate(grid):
        for j, cell in enumerate(row):
            if cell == 'S':
                start = (i, j)
            elif cell == 'E':
                end = (i, j)
            elif cell not in 'SE.#':
                raise ValueError("Invalid character in grid")

    if start is None or end is None:
        raise ValueError("Grid must contain exactly one 'S' and one 'E'")

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    queue = deque([(start, 0)])
    visited = set([start])

    while queue:
        (x, y), steps = queue.popleft()
        if (x, y) == end:
            return steps

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols and (nx, ny) not in visited and grid[nx][ny] != '#':
                visited.add((nx, ny))
                queue.append(((nx, ny), steps + 1))

    return -1
